<template><view class="card"><text class="title">个人资料</text><image v-if="form.avatar" :src="asset(form.avatar)" mode="aspectFill"/><!-- #ifdef MP-WEIXIN --><button class="ui-button" open-type="chooseAvatar" @chooseavatar="chooseAvatar" :disabled="busy">使用微信头像</button><!-- #endif --><!-- #ifndef MP-WEIXIN --><button class="ui-button" @click="pick" :disabled="busy">选择头像</button><!-- #endif --><text class="field-label">昵称</text><!-- #ifdef MP-WEIXIN --><input type="nickname" class="profile-input" v-model="form.nickname" @blur="form.nickname=$event.detail.value" maxlength="40" placeholder="填写或选择微信昵称"/><!-- #endif --><!-- #ifndef MP-WEIXIN --><input class="profile-input" v-model="form.nickname" maxlength="40" placeholder="您的昵称"/><!-- #endif --><text class="field-label">联系手机号（选填）</text><input class="profile-input" v-model="form.contactPhone" type="number" maxlength="11" placeholder="联系手机号（选填）"/><text class="hint">联系电话用于联系您，未经短信核验，不会改变登录账号。</text><button class="ui-button" :disabled="busy" @click="save">保存个人资料</button></view></template>
<script>import {request,asset,uploadPublicImage,notify} from '../services/shop.js';export default {props:{member:Object},data(){return{form:{nickname:this.member?.nickname||'',avatar:this.member?.avatar||'',contactPhone:this.member?.contact_phone||''},busy:false}},methods:{asset,chooseAvatar(e){const path=e.detail.avatarUrl;if(path)this.act(async()=>{this.form.avatar=await uploadPublicImage(path)})},pick(){uni.chooseImage({count:1,success:r=>this.act(async()=>{this.form.avatar=await uploadPublicImage(r.tempFilePaths[0])})})},async act(fn){if(this.busy)return;this.busy=true;try{await fn()}catch(e){notify(e)}finally{this.busy=false}},save(){this.act(async()=>{await request('/account/profile','POST',this.form);uni.showToast({title:'资料已保存',icon:'success'});this.$emit('saved')})}}}</script><style scoped>
@import '../styles/component-base.css';
.card{background:var(--shop-surface, #fdfeff);padding:18px;margin:16px;border-radius:12px;font-size:16px}.title{font-weight:bold;font-size:19px}.hint{display:block;color:var(--shop-ink, #28546c);line-height:1.6;font-size:14px}.field-label{display:block;font-size:14px;margin:14px 0 7px;color:var(--shop-ink, #28546c)}.profile-input{display:block;width:100%;height:46px;min-height:46px;box-sizing:border-box;background:var(--shop-background, #f3f8fb);border:1px solid var(--shop-border, #d5e6ee);border-radius:6px;padding:0 12px;margin:0 0 12px;font-size:16px;line-height:normal;color:var(--shop-text, #2b424f)}button{font-size:16px;margin:10px 0;color:var(--shop-ink, #28546c)}image{display:block;width:70px;height:70px;border-radius:50%;margin:12px 0}</style>